/bin/bash -c "set -e
python3 -m py_compile openai_client.py
python3 - <<'PY'
import http.client
import json
import openai_client

sample_response = {
    \"output\": [
        {
            \"type\": \"message\",
            \"content\": [
                {\"type\": \"output_text\", \"text\": \"Hello, \"},
                {\"type\": \"output_text\", \"text\": \"world"'!"},
            ],
        }
    ]
}
assert openai_client.OpenAIResponsesClient.get_text(sample_response) == "Hello, world!"

for base_url, expected_path in [
    ("https://api.openai.com/v1", "/v1/responses"),
    ("https://example.test/api/v1/", "/api/v1/responses"),
]:
    client = openai_client.OpenAIResponsesClient(
        api_key="[REDACTED_SECRET]", api_base_url=base_url
    )
    assert client._request_path == expected_path

captured = {}

class FakeResponse:
    status = 200
    def read(self):
        return json.dumps(sample_response).encode("utf-8")
    def getheader(self, name):
        return None

class FakeConnection:
    def __init__(self, host, port, timeout):
        captured.update(host=host, port=port, timeout=timeout)
    def request(self, method, path, body=None, headers=None):
        captured.update(method=method, path=path, body=json.loads(body), headers=headers)
    def getresponse(self):
        return FakeResponse()
    def close(self):
        pass

original_connection = http.client.HTTPSConnection
http.client.HTTPSConnection = FakeConnection
try:
    client = openai_client.OpenAIResponsesClient(api_key="[REDACTED_SECRET]")
    result = client.send_text("private prompt", "test-model")
finally:
    http.client.HTTPSConnection = original_connection

assert result == "Hello, world!"
assert captured["method"] == "POST"
assert captured["path"] == "/v1/responses"
assert captured["body"] == {
    "model": "test-model",
    "input": "private prompt",
    "store": False,
}
assert captured["headers"]["Authorization"] == "Bearer test-key"

try:
    openai_client.OpenAIResponsesClient(
        api_key="[REDACTED_SECRET]", api_base_url="http://api.openai.com/v1"
    )
except ValueError:
    pass
else:
    raise AssertionError("HTTP URLs must be rejected")

try:
    openai_client.OpenAIResponsesClient(api_key="[REDACTED_SECRET]")
    client._raise_api_error(
        401,
        b'"'{\"error\":{\"message\":\"Invalid API key\"}}',
        \"request-id\",
    )
except openai_client.OpenAIAuthenticationError as exc:
    assert str(exc) == \"Invalid API key\"
    assert exc.status_code == 401
    assert exc.request_id == \"request-id\"
else:
    raise AssertionError(\"authentication errors must use the dedicated class\")

print(\"syntax, request, parsing, validation, and error tests passed\")
PY"

